    return `<tr><td>${escapeHtml(objectName(record))}<br>${escapeHtml(address(record))}</td><td>\u5C31\u7EEA\u6A21\u677F ID\uFF1A${shown(ready.templateId)}<br>\u62A5\u544A\u6A21\u677F ID\uFF1A${shown(run.templateId ?? report.templateId)}<br>\u62A5\u544A\u4E3B\u4F53\u8D44\u4EA7 ID\uFF1A${shown(run.assetId)}<br>\u6A21\u677F\u5185\u5BB9\u7248\u672C\uFF1A\u672A\u6838\u5B9E</td><td>${recordPills(record)}<br>\u901A\u8FC7\u6807\u5FD7\uFF08\u539F\u503C\uFF09\uFF1A${shown(run.passFlag)}<br>\u9002\u7528\u9879 / \u6A21\u677F\u6210\u5458\uFF1A${shown(ready.applicableCount)} / ${shown(ready.memberCount)}<br>\u8303\u56F4\u5339\u914D\uFF08\u539F\u503C\uFF09\uFF1A${shown(ready.templateScopeMatched)}<br>\u8986\u76D6\u539F\u56E0\uFF1A${shown(ready.coverageReason)}<br>\u672A\u68C0\u67E5\u539F\u56E0\uFF1A${shown(run.notCheckedReason)}<br>${escapeHtml(explanation(record))}</td><td>\u672C\u6B21\u8BFB\u53D6\uFF1A${shown(record.source.observed_at)}<br>\u539F\u62A5\u544A\u6838\u67E5\u65F6\u95F4\uFF1A\u5F53\u524D\u7ED3\u679C\u672A\u63D0\u4F9B<br>${escapeHtml(text(facts.consistency) || "\u6A21\u677F\u7248\u672C\u3001\u62A5\u544A\u65F6\u6548\u53CA\u8BFB\u53D6\u4E00\u81F4\u6027\u672A\u6838\u5B9E")}</td></tr>`;
  }).join("")}</tbody></table></div>` : `<p>${baselineSections.length ? "\u57FA\u7EBF\u7EF4\u5EA6\u5B58\u5728\uFF0C\u4F46\u6CA1\u6709\u53D6\u5F97\u8BBE\u5907\u660E\u7EC6\uFF1B\u7F3A\u53E3\u4FDD\u7559\u5728\u540E\u7EED\u6E05\u5355\u3002" : "\u672C\u6B21\u672A\u5305\u542B\u57FA\u7EBF\u6838\u67E5\uFF0C\u4E0D\u80FD\u8BA1\u7B97\u57FA\u7EBF\u901A\u8FC7\u7387\u3002"}</p>`}</section>`;
  function detailTable(records, interactive) {
    return `<div class="table-wrap"><table><caption>${interactive ? "\u5F02\u5E38\u3001\u672A\u77E5\u3001\u5931\u8D25\u3001\u4E0D\u9002\u7528\u53CA\u8986\u76D6\u7F3A\u53E3\uFF1B\u4E0D\u622A\u65AD\u8BB0\u5F55" : "\u5B8C\u6574\u68C0\u67E5\u660E\u7EC6\uFF0C\u5305\u542B\u6B63\u5E38\u7ED3\u679C\u53CA\u6240\u6709\u6D3E\u751F\u8986\u76D6\u7F3A\u53E3"}</caption><thead><tr><th scope="col">\u7EF4\u5EA6 / \u5BF9\u8C61</th><th scope="col">\u7ED3\u679C\u4E0E\u8BC1\u636E\u6458\u8981</th><th scope="col">\u5F71\u54CD / \u8D23\u4EFB / \u4F18\u5148\u7EA7</th><th scope="col">\u72B6\u6001${interactive ? " / \u64CD\u4F5C" : ""}</th></tr></thead><tbody>${records.map((record) => {
