    }).join("")}</tbody></table></div>`;
  }
  function evidence(record, interactive, first) {
    const item = record.source, facts = object(item.facts), observedState = object(facts.stateEvidence ?? item.stateEvidence);
    const attributes = interactive ? ` data-evidence-panel="${escapeHtml(record.id)}"${first ? "" : " hidden"}` : "";
    const limitations = record.category === "\u4E1A\u52A1" ? "\u8BA1\u7B97\u8DEF\u5F84\u3001\u7B56\u7565\u7ED3\u679C\u4E0E\u4E1A\u52A1\u5E94\u7528\u5B9E\u9645\u54CD\u5E94\u662F\u4E0D\u540C\u8BC1\u636E\uFF1B\u672A\u6267\u884C\u4E3B\u52A8\u63A2\u6D4B\u3002" : record.category === "\u6F0F\u6D1E" ? "\u6309SOC\u5DF2\u6709\u6F0F\u6D1E\u6570\u636E\u5448\u73B0\uFF1B\u5B8C\u6574\u6210\u529F\u7684\u7A7A\u7ED3\u679C\u4E3A\u6CA1\u6709\u6F0F\u6D1E\uFF0C\u8BFB\u53D6\u5931\u8D25\u6216\u672A\u5B8C\u6210\u5355\u72EC\u4FDD\u7559\u3002" : record.category === "\u57FA\u7EBF" ? "\u8BFB\u53D6\u62A5\u544A\u6807\u5FD7\u4E0D\u8BC1\u660E\u6A21\u677F\u5185\u5BB9\u7248\u672C\u4E0E\u62A5\u544A\u65F6\u6548\uFF1B\u672A\u8FD4\u56DE\u6A21\u677F\u6216\u62A5\u544A\u4E0D\u80FD\u89C6\u4E3A\u901A\u8FC7\u3001\u4E0D\u9002\u7528\u3002" : record.category === "\u8BBE\u5907" ? "\u9ED8\u8BA4SOC\u6570\u636E\u4E3A\u6700\u65B0\uFF0C\u76F4\u63A5\u5448\u73B0SOC\u5728\u7EBF\u6216\u79BB\u7EBF\u72B6\u6001\uFF1Bunknown\u663E\u793ASOC\u672A\u91C7\u96C6\u5230\u72B6\u6001\u6570\u636E\uFF0C\u4E0D\u5728\u672C\u7AEF\u56E0\u65F6\u95F4\u6216\u5FC3\u8DF3\u6539\u5224\u3002" : "\u4EC5\u4FDD\u7559\u5DF2\u77E5\u53EF\u5C55\u793A\u5B57\u6BB5\uFF1B\u6CA1\u6709\u63D0\u4F9B\u7684\u4E8B\u5B9E\u4E0D\u4F5C\u8865\u9F50\u3002";
    return `<section class="card"${attributes}><h3${interactive ? ' tabindex="-1"' : ""}>\u8BC1\u636E\u8BE6\u60C5 \xB7 ${escapeHtml(objectName(record))} ${recordPills(record)}</h3><dl class="grid two"><div><dt>\u68C0\u67E5\u7EF4\u5EA6</dt><dd>${escapeHtml(record.section)}</dd></div><div><dt>\u7A33\u5B9A\u8EAB\u4EFD / \u5730\u5740</dt><dd>${escapeHtml(address(record))}</dd></div><div><dt>\u672C\u6B21\u8BFB\u53D6\u65F6\u95F4</dt><dd>${shown(item.observed_at)}</dd></div><div><dt>\u4E0A\u6E38\u89C2\u6D4B\u65F6\u95F4</dt><dd>${shown(facts.lastSeenAt ?? facts.lastProbeAt, "\u5F53\u524D\u7ED3\u679C\u672A\u63D0\u4F9B\u72EC\u7ACB\u4E0A\u6E38\u89C2\u6D4B\u65F6\u95F4\uFF1B\u9010\u4FE1\u53F7 observedAt \u89C1\u5B89\u5168\u8BC1\u636E")}</dd></div><div><dt>SOC \u72B6\u6001\u8BC4\u4F30\u65F6\u95F4 / \u65F6\u95F4\u57FA\u51C6</dt><dd>${shown(observedState.evaluatedAt)} / ${shown(observedState.timeBasis)}</dd></div></dl><p>${escapeHtml(explanation(record))}</p><p>${escapeHtml(limitations)}</p>${present(item.recommendation) ? `<p><strong>\u6765\u6E90\u5EFA\u8BAE \xB7 \u5EFA\u8BAE\uFF0C\u672A\u6267\u884C\uFF1A</strong>${escapeHtml(item.recommendation)}</p>` : "<p>\u672A\u63D0\u4F9B\u9488\u5BF9\u6027\u5904\u7F6E\u5EFA\u8BAE\uFF1B\u4E0D\u636E\u7ED3\u679C\u8BF4\u660E\u81EA\u52A8\u5224\u65AD\u6839\u56E0\u3002</p>"}<p>\u4E1A\u52A1\u5F71\u54CD\u3001\u8D23\u4EFB\u4EBA\u548C\u4F18\u5148\u7EA7\u672A\u63D0\u4F9B\u3002${record.gap ? "\u4EE5\u4E0B\u4EC5\u4E3A\u5C55\u793A\u5C42\u7F3A\u53E3\u8BF4\u660E\uFF0C\u4E0D\u4F2A\u88C5\u4E3A\u6765\u6E90\u68C0\u67E5\u6761\u76EE\u3002" : "\u4EE5\u4E0B\u4E3A\u5B8C\u6574\u7684\u5DF2\u77E5\u5B57\u6BB5\u5B89\u5168\u6295\u5F71\uFF0C\u4E0D\u662F\u5B8C\u6574\u539F\u59CB\u54CD\u5E94\uFF1B\u672A\u77E5 / \u654F\u611F\u5B57\u6BB5\u4E0D\u8F93\u51FA\u3002"}</p><pre>${jsonText(safeProjection(item))}</pre></section>`;
  }
  const filters = `<div class="filters"><label for="report-search">\u641C\u7D22\u5BF9\u8C61\u3001\u5730\u5740\u3001\u72B6\u6001\u6216\u8BF4\u660E</label> <input type="search" id="report-search" autocomplete="off" placeholder="\u641C\u7D22\u5DF2\u4FDD\u5B58\u660E\u7EC6">${["\u5168\u90E8", ...CATEGORIES].map((category) => `<button type="button" class="btn${category === "\u5168\u90E8" ? " active" : ""}" data-filter="${escapeHtml(category)}" aria-pressed="${category === "\u5168\u90E8" ? "true" : "false"}">${escapeHtml(category)}</button>`).join("")}</div>`;
  const interactiveDetails = `<section class="card"><h2>\u5F02\u5E38\u3001\u672A\u77E5\u4E0E\u4E0D\u9002\u7528\u660E\u7EC6</h2><p>\u7B5B\u9009\u53EA\u6539\u53D8\u672C\u9875\u5C55\u793A\uFF0C\u4E0D\u6539\u53D8\u7EDF\u8BA1\u4E0E\u5B8C\u6574\u6253\u5370\u8F7D\u8377\uFF1B\u6309\u884C Enter / \u7A7A\u683C\u6216\u201C\u67E5\u770B\u8BC1\u636E\u8BE6\u60C5\u201D\u6253\u5F00\u8BC1\u636E\u3002</p>${filters}<p id="filter-status" role="status" aria-live="polite">\u5F53\u524D\u5217\u51FA ${attention.length} \u6761\u5173\u6CE8\u8BB0\u5F55\uFF1B\u6B63\u5E38\u7ED3\u679C\u5B8C\u6574\u4FDD\u7559\u4E8E\u5B89\u5168\u9644\u5F55\u3002</p>${detailTable(attention, true)}<p id="no-matches" hidden>\u5F53\u524D\u7B5B\u9009\u6CA1\u6709\u5339\u914D\u8BB0\u5F55\uFF1B\u8FD9\u4E0D\u4EE3\u8868\u5DE1\u68C0\u5DF2\u901A\u8FC7\u3002</p>${attention.length ? "" : "<p>\u5F53\u524D\u6CA1\u6709\u5DF2\u5B58\u5173\u6CE8\u6761\u76EE\uFF1B\u662F\u5426\u5B58\u5728\u672A\u68C0\u67E5\u7EF4\u5EA6\u3001\u8986\u76D6\u4E0D\u8DB3\u6216\u9002\u7528\u9650\u5236\uFF0C\u4ECD\u987B\u7ED3\u5408\u6307\u6807\u548C\u7F3A\u53E3\u8BF4\u660E\u3002</p>"}</section>${attention.map((record, index) => evidence(record, true, index === 0)).join("")}`;
  const printableDetails = `<section class="card"><h2>\u5168\u91CF\u68C0\u67E5\u660E\u7EC6 \xB7 \u72EC\u7ACB\u6253\u5370</h2><p>\u4EE5\u4E0B\u6309\u5B8C\u6574\u5217\u8868\u751F\u6210\uFF0C\u5305\u542B\u6B63\u5E38\u3001\u5F02\u5E38\u3001\u672A\u77E5\u3001\u5931\u8D25\u3001\u4E0D\u9002\u7528\u4E0E\u6D3E\u751F\u7F3A\u53E3\uFF0C\u4E0D\u4F9D\u8D56\u9875\u9762\u5F53\u524D\u641C\u7D22\u6216\u9009\u4E2D\u72B6\u6001\u3002</p>${detailTable(allRecords, false)}</section>${allRecords.map((record) => evidence(record, false, false)).join("")}`;
  const sourceRecommendations = sourceRecords.filter((record) => present(record.source.recommendation));
  const recommendations = `<section class="card"><h2>\u5EFA\u8BAE \xB7 \u672A\u6267\u884C</h2><p>\u4EE5\u4E0B\u4EC5\u6574\u7406\u6765\u6E90\u5EFA\u8BAE\u6216\u7ED9\u51FA\u590D\u6838\u65B9\u5411\uFF0C\u4E0D\u4EE3\u8868\u5DF2\u6267\u884C\u6574\u6539\u3001\u5DF2\u9A8C\u8BC1\u6839\u56E0\u6216\u5DF2\u5206\u6D3E\u8D23\u4EFB\u3002</p>${sourceRecommendations.length ? `<ul>${sourceRecommendations.map((record) => `<li><strong>${escapeHtml(record.section)} \xB7 ${escapeHtml(objectName(record))}</strong>\uFF1A${escapeHtml(record.source.recommendation)} <span class="pill neutral">\u6765\u6E90\u5EFA\u8BAE\uFF0C\u672A\u6267\u884C</span></li>`).join("")}</ul>` : "<p>\u5F53\u524D\u7ED3\u679C\u6CA1\u6709\u63D0\u4F9B\u9488\u5BF9\u6027\u5EFA\u8BAE\uFF1B\u4E0D\u81EA\u52A8\u7F16\u9020\u4FEE\u590D\u63AA\u65BD\u3002</p>"}<p><strong>\u6574\u7406\u5EFA\u8BAE\uFF0C\u672A\u6267\u884C\uFF1A</strong>\u5148\u6838\u5BF9\u6765\u6E90\u7F3A\u53E3\u3001\u8303\u56F4\u8EAB\u4EFD\u4E0E\u8BC1\u636E\u65F6\u6548\uFF0C\u518D\u5728\u76F8\u540C\u6388\u6743\u8303\u56F4\u5185\u590D\u67E5\uFF1B\u5F02\u5E38\u7ED3\u8BBA\u4E0E\u672A\u5B8C\u6210\u9879\u5206\u522B\u5904\u7406\u3002\u672A\u8BB0\u5F55\u8D23\u4EFB\u4EBA\u3001\u4F18\u5148\u7EA7\u6216\u4E1A\u52A1\u5F71\u54CD\u65F6\uFF0C\u5E94\u7531\u6709\u6743\u4EBA\u5458\u8865\u5145\uFF0C\u800C\u4E0D\u662F\u7531\u6E32\u67D3\u5668\u63A8\u6D4B\u3002</p></section>`;
  const gapMessages = [...globalGaps, ...sections.flatMap((section) => section.gaps.map((gap) => `${section.title}\uFF1A${gap}`))];
  const gaps = `<section class="card"><h2>\u6765\u6E90\u7F3A\u53E3\u4E0E\u9002\u7528\u8FB9\u754C</h2>${gapMessages.length ? `<ul>${gapMessages.map((message) => `<li>${escapeHtml(message)}</li>`).join("")}</ul>` : "<p>\u672A\u53D1\u73B0\u672C\u6B21\u7ED3\u6784\u3001\u8BA1\u6570\u4E0E\u8303\u56F4\u6838\u5BF9\u7F3A\u53E3\uFF1B\u8FD9\u4E0D\u7B49\u4E8E\u5B8C\u6210\u4E3B\u52A8\u9A8C\u8BC1\u6216\u6392\u9664\u6240\u6709\u5B89\u5168\u98CE\u9669\u3002</p>"}<ul><li>\u672A\u77E5 ${uncertainRecords.filter((record) => record.status === "unknown").length} \u6761\u3001\u5931\u8D25 ${uncertainRecords.filter((record) => record.status === "failed").length} \u6761\u4ECD\u4FDD\u7559\uFF1B\u7F3A\u5931\u548C\u672A\u68C0\u67E5\u4E0D\u4F5C\u4E3A\u96F6\u6216\u6B63\u5E38\u3002</li><li>\u4E0D\u9002\u7528\u4EC5\u91C7\u7528\u6765\u6E90\u660E\u786E\u7ED3\u8BBA\uFF0C\u4E0D\u7531\u7A7A\u6A21\u677F\u3001\u7A7A\u62A5\u544A\u6216\u65E0\u89C4\u5219\u63A8\u65AD\u3002</li><li>\u672A\u6267\u884C\u4E3B\u52A8\u63A2\u6D4B\uFF1B\u6CA1\u6709\u62A5\u544A\u65F6\u6548\u3001\u6A21\u677F\u7248\u672C\u3001\u626B\u63CF\u8986\u76D6\u3001\u4E1A\u52A1\u5B9E\u9645\u54CD\u5E94\u6216\u4EBA\u5DE5\u590D\u6838\u8BC1\u636E\u65F6\uFF0C\u5747\u4FDD\u6301\u672A\u6838\u5B9E\u3002</li><li>\u5B89\u5168\u6295\u5F71\u4F1A\u6392\u9664\u672A\u77E5\u4E0E\u654F\u611F\u5B57\u6BB5\uFF1B\u5B89\u5168\u9644\u5F55\u4E0D\u66FF\u4EE3\u53D7\u63A7\u4FDD\u5B58\u7684\u539F\u59CB\u4E8B\u5B9E\uFF0C\u4E0D\u80FD\u636E\u672A\u663E\u793A\u5B57\u6BB5\u8BA4\u5B9A\u5176\u4E0D\u5B58\u5728\u3002</li></ul></section>`;
  const appendixView = safeProjection({
